const measuredCells=[0,5,11];
const NOMINAL_AH=60;
let data=[];
let idx=0,timer=null,running=false;
const $=id=>document.getElementById(id);
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));

function csvParse(text){
  const lines=text.trim().split(/\r?\n/); if(lines.length<2)return [];
  const headers=lines[0].split(",").map(x=>x.trim());
  return lines.slice(1).map(line=>{
    const vals=line.split(","),o={};
    headers.forEach((h,i)=>o[h]=Number(vals[i]));
    return o;
  });
}
function loadRows(rows){
  data=rows.filter(r=>r&&Number.isFinite(Number(r.pack_current_A))).map(r=>{
    const o={}; for(const [k,v] of Object.entries(r))o[k]=Number(v); return o;
  });
  idx=0; render();
}
$("file").addEventListener("change",async e=>{
  const f=e.target.files[0];if(!f)return;
  try{
    const text=await f.text();
    loadRows(f.name.toLowerCase().endsWith(".json")?JSON.parse(text):csvParse(text));
  }catch(err){alert("Could not read this sensor file.");}
});

function operatingMode(I){
  if(I<-2)return {name:"CHARGING",color:"#0ea5e9",reason:`Charge current ${Math.abs(I).toFixed(1)} A`};
  if(I>2)return {name:"DISCHARGING",color:"#f59e0b",reason:`Load current ${I.toFixed(1)} A`};
  return {name:"IDLE / REST",color:"#64748b",reason:"Pack current is near zero"};
}

function model(r){
  const I=r.pack_current_A, amb=r.ambient_C;
  const initialTemp=36.5;
  const temps=Array(12).fill(initialTemp);
  const sensed=[r.T1_C,r.T2_C,r.T3_C];

  // Start the virtual pack from one uniform temperature. The fault is active
  // from t=0, but it should not create an artificial temperature jump in the
  // first frame. The temperature divergence develops during the discharge.
  if(Number(r.time_s)>0){
    measuredCells.forEach((cell,j)=>temps[cell]=sensed[j]);
  }

  // Fault is active from the first frame so the demo opens directly in the
  // abnormal state. Cell 6 is deliberately degraded: resistance increases
  // and its temperature is driven upward by the additional I²R loss.
  const faultProgress=clamp(r.time_s/90,0,1);
  const faultRFactor=1.55 + 0.45*faultProgress; // 1.55x -> 2.0x nominal
  const faultSOH=88.0 - 2.0*faultProgress;      // 88% -> 86% effective SOH
  const cell6Heat=Math.max(I,0)**2*0.000075;

  for(let i=0;i<12;i++){
    if(!measuredCells.includes(i)){
      const rr=Math.floor(i/4),cc=i%4,neighbors=[];
      measuredCells.forEach(m=>{
        const mr=Math.floor(m/4),mc=m%4,d=Math.abs(rr-mr)+Math.abs(cc-mc);
        if(d<=2)neighbors.push(temps[m]);
      });
      const avg=neighbors.length?neighbors.reduce((a,b)=>a+b,0)/neighbors.length:amb+3;
      const heating=Math.max(I,0)**2*0.000035 + Math.max(-I,0)**2*0.00002;
      temps[i]=avg+heating+0.15*Math.sin(i*1.7+r.time_s/50);
    }
  }

  // Cell 6 starts at exactly the same temperature as every other cell.
  // Its higher resistance is active from t=0, and the thermal signature grows
  // progressively with I²R heating so the abnormality develops naturally.
  if(Number(r.time_s)>0){
    const baseT=temps[5];
    const faultThermalRise=2.0*faultProgress + 7.0*faultProgress*faultProgress;
    temps[5]=baseT + faultThermalRise;
  }

  const expectedTout=r.coolant_in_C+0.0105*Math.abs(I);
  const residual=r.coolant_out_C-expectedTout;

  const cellSOH=Array.from({length:12},(_,i)=>i===5?faultSOH:99.2-0.4*(i%3));
  const packSOH=Math.min(...cellSOH);
  const resistance=12*(100/packSOH);
  return {temps,cellSOH,packSOH,resistance,residual,faultProgress,faultRFactor,faultSOH};
}

function estimateCellSOC(r, cellSOH){
  // Coulomb-count each cell from the initial measured pack SOC.
  // Cells are in series, so the same current flows through each cell.
  // Capacity differs slightly with SOH; degraded cells therefore move faster in SOC.
  const n=12, initialSoc=data.length ? Number(data[0].soc_pct) : Number(r.soc_pct);
  const ahThrough=new Array(n).fill(0);
  for(let k=1;k<=idx && k<data.length;k++){
    const a=data[k-1], b=data[k];
    const dt=Math.max(0,Number(b.time_s)-Number(a.time_s));
    const Iavg=(Number(a.pack_current_A)+Number(b.pack_current_A))/2;
    const prevModel=model(a);
    const currModel=model(b);
    for(let i=0;i<n;i++){
      const sohAvg=((prevModel.cellSOH[i]+currModel.cellSOH[i])/2)/100;
      const q=Math.max(1,NOMINAL_AH*sohAvg);
      ahThrough[i] += Iavg*dt/(3600*q);
    }
  }
  let socs=ahThrough.map(v=>clamp(initialSoc/100-v,0,1)*100);

  // Anchor the mean cell SOC to the BMS pack SOC while preserving
  // the cell-to-cell spread caused by different capacities.
  const target=Number(r.soc_pct);
  const mean=socs.reduce((a,b)=>a+b,0)/n;
  const offset=target-mean;
  socs=socs.map(v=>clamp(v+offset,0,100));
  return socs;
}

function svgSocChart(){
  const start=Math.max(0,idx-180), arr=data.slice(start,idx+1);
  if(!arr.length)return;
  const W=760,H=250,pad=32,min=Math.max(0,Math.min(...arr.map(r=>r.soc_pct))-4),max=Math.min(100,Math.max(...arr.map(r=>r.soc_pct))+2);
  const x=j=>pad+j*(W-2*pad)/Math.max(1,arr.length-1);
  const y=v=>H-pad-(v-min)/(max-min)*(H-2*pad);
  const p1=arr.map((r,j)=>[x(j),y(r.soc_pct)]);
  const p2=arr.map((r,j)=>[x(j),y(estimateCellSOC(r,model(r).cellSOH)[5])]);
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%">
    <line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/>
    <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${H-pad}" stroke="#cbd5e1"/>`;
  svg+=svgLine(p1,"#16a66a",3)+svgLine(p2,"#2563eb",3,"8 6");
  const a=p1[p1.length-1],b=p2[p2.length-1];
  svg+=`<circle cx="${a[0]}" cy="${a[1]}" r="4" fill="#16a66a"/>
         <circle cx="${b[0]}" cy="${b[1]}" r="4" fill="#2563eb"/>
         <text x="${pad}" y="15" font-size="11" fill="#64748a">SOC (%)</text>
         <text x="${W-pad-38}" y="${H-7}" font-size="11" fill="#64748a">time</text></svg>`;
  $("socChart").innerHTML=svg;
}

function setMode(r){
  const m=operatingMode(r.pack_current_A);
  $("operatingMode").textContent=m.name;
  $("modeReason").textContent=m.reason;
  $("modeDot").style.background=m.color;
  $("modeDot").style.boxShadow=`0 0 0 5px ${m.color}22`;
  $("modeValue").textContent=m.name;
  $("modeMetric").style.borderTopColor=m.color;
}

function svgLine(points,color,width=3,dash=""){
  return `<polyline fill="none" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:``} points="${points.map(p=>p.join(",")).join(" ")}"/>`;
}

function drawTempChart(){
  const start=Math.max(0,idx-180),arr=data.slice(start,idx+1);if(!arr.length)return;
  const W=760,H=250,pad=32,min=28,max=55;
  const x=j=>pad+j*(W-2*pad)/Math.max(1,arr.length-1);
  const y=t=>H-pad-(t-min)/(max-min)*(H-2*pad);
  const p1=arr.map((r,j)=>[x(j),y(r.T2_C)]);
  const p2=arr.map((r,j)=>[x(j),y(model(r).temps[5])]);
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${H-pad}" stroke="#cbd5e1"/>`;
  svg+=svgLine(p1,"#16a66a",3)+svgLine(p2,"#2563eb",3,"8 6");
  const last1=p1[p1.length-1],last2=p2[p2.length-1];
  svg+=`<circle cx="${last1[0]}" cy="${last1[1]}" r="4" fill="#16a66a"/><circle cx="${last2[0]}" cy="${last2[1]}" r="4" fill="#2563eb"/>`;
  svg+=`<text x="${pad}" y="15" font-size="11" fill="#64748a">Temperature (°C)</text><text x="${W-pad-38}" y="${H-7}" font-size="11" fill="#64748a">time</text></svg>`;
  $("tempChart").innerHTML=svg;
}



function drawHealthChart(health){
  const W=760,H=210,pad=32;
  const vals=health.map(x=>x.soh),min=90,max=100;
  const bw=(W-2*pad)/health.length*0.62;
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/><text x="${pad}" y="15" font-size="11" fill="#64748a">Estimated SOH (%)</text>`;
  health.forEach((c,i)=>{
    const xx=pad+i*(W-2*pad)/health.length+(W-2*pad)/health.length*0.19;
    const yy=H-pad-(c.soh-min)/(max-min)*(H-2*pad);
    const hh=H-pad-yy;
    const col=i===5?"#2563eb":"#16a66a";
    svg+=`<rect x="${xx}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="${col}"/><text x="${xx+bw/2}" y="${H-pad+15}" text-anchor="middle" font-size="9" fill="#64748a">C${i+1}</text><text x="${xx+bw/2}" y="${yy-5}" text-anchor="middle" font-size="9" font-weight="700" fill="${col}">${c.soh.toFixed(1)}</text>`;
  });
  svg+=`</svg>`;$("healthChart").innerHTML=svg;
}

function chartShell(W,H){
  const pad=34;
  return {W,H,pad,x:j=>pad+j*(W-2*pad)/Math.max(1,180),y:(v,min,max)=>H-pad-(v-min)/(max-min)*(H-2*pad)};
}

function drawAllTempChart(){
  const start=Math.max(0,idx-180),arr=data.slice(start,idx+1); if(!arr.length)return;
  const W=760,H=270,pad=34,min=30,max=52;
  const x=j=>pad+j*(W-2*pad)/Math.max(1,arr.length-1);
  const y=v=>H-pad-(v-min)/(max-min)*(H-2*pad);
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${H-pad}" stroke="#cbd5e1"/><text x="${pad}" y="15" font-size="11" fill="#64748a">Temperature (°C)</text>`;
  for(let i=0;i<12;i++){
    const pts=arr.map((r,j)=>[x(j),y(model(r).temps[i])]);
    const col=i===5?"#ef4444":(measuredCells.includes(i)?"#16a66a":"#2563eb");
    svg+=svgLine(pts,col,i===5?4:1.7,i===5?"":"4 4");
    if(arr.length){const q=pts[pts.length-1];svg+=`<circle cx="${q[0]}" cy="${q[1]}" r="${i===5?4:2}" fill="${col}"/>`;}
  }
  svg+=`<text x="${W-pad-35}" y="${H-7}" font-size="11" fill="#64748a">time</text></svg>`;
  $("allTempChart").innerHTML=svg;
}

function drawResistanceChart(m){
  const W=760,H=250,pad=38,min=11,max=Math.max(26,12*m.faultRFactor+2);
  const bw=(W-2*pad)/12*0.62;
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/><text x="${pad}" y="15" font-size="11" fill="#64748a">Resistance (mΩ)</text>`;
  m.cellSOH.forEach((soh,i)=>{
    const R=i===5?12*m.faultRFactor:12*(100/soh);
    const xx=pad+i*(W-2*pad)/12+(W-2*pad)/12*0.19;
    const yy=H-pad-(R-min)/(max-min)*(H-2*pad),hh=H-pad-yy;
    const col=i===5?"#ef4444":"#2563eb";
    svg+=`<rect x="${xx}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="${col}"/><text x="${xx+bw/2}" y="${H-pad+15}" text-anchor="middle" font-size="9" fill="#64748a">C${i+1}</text><text x="${xx+bw/2}" y="${yy-5}" text-anchor="middle" font-size="9" font-weight="700" fill="${col}">${R.toFixed(1)}</text>`;
  });
  svg+=`</svg>`;$("resistanceChart").innerHTML=svg;
}

function drawCellSocChart(cellSOC){
  const W=760,H=250,pad=38,min=Math.max(0,Math.min(...cellSOC)-2),max=Math.min(100,Math.max(...cellSOC)+2);
  const bw=(W-2*pad)/12*0.62;
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#cbd5e1"/><text x="${pad}" y="15" font-size="11" fill="#64748a">SOC (%)</text>`;
  cellSOC.forEach((v,i)=>{
    const xx=pad+i*(W-2*pad)/12+(W-2*pad)/12*0.19;
    const yy=H-pad-(v-min)/(max-min)*(H-2*pad),hh=H-pad-yy;
    const col=i===5?"#ef4444":"#2563eb";
    svg+=`<rect x="${xx}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="${col}"/><text x="${xx+bw/2}" y="${H-pad+15}" text-anchor="middle" font-size="9" fill="#64748a">C${i+1}</text><text x="${xx+bw/2}" y="${yy-5}" text-anchor="middle" font-size="9" font-weight="700" fill="${col}">${v.toFixed(1)}</text>`;
  });
  svg+=`</svg>`;$("cellSocChart").innerHTML=svg;
}

function render(){
  if(!data.length)return;
  const r=data[idx%data.length],m=model(r),cellSOC=estimateCellSOC(r,m.cellSOH),mode=operatingMode(r.pack_current_A);
  setMode(r);
  $("current").textContent=r.pack_current_A.toFixed(1)+" A";
  $("voltage").textContent=r.pack_voltage_V.toFixed(2)+" V";
  $("soc").textContent=r.soc_pct.toFixed(1)+" %";
  $("tout").textContent=r.coolant_out_C.toFixed(1)+" °C";

  const dr=Math.max(0,r.pack_current_A)/NOMINAL_AH;
  const cr=Math.max(0,-r.pack_current_A)/NOMINAL_AH;
  $("rateValue").textContent=dr.toFixed(2)+" C";
  $("drate").textContent=dr.toFixed(2)+" C";
  $("crate").textContent=cr.toFixed(2)+" C";
  $("cycle").textContent=mode.name;

  $("sensors").innerHTML=[
    ["Pack current",r.pack_current_A.toFixed(1)+" A"],["Pack voltage",r.pack_voltage_V.toFixed(2)+" V"],
    ["SOC",r.soc_pct.toFixed(1)+" %"],["Ambient",r.ambient_C.toFixed(1)+" °C"],
    ["Coolant inlet",r.coolant_in_C.toFixed(1)+" °C"],["Coolant outlet",r.coolant_out_C.toFixed(1)+" °C"],
    ["Coolant flow",r.coolant_flow_Lmin.toFixed(2)+" L/min"],
    ["T1–T3", [r.T1_C,r.T2_C,r.T3_C].map(x=>Number(x).toFixed(1)+"°C").join(" / ")]
  ].map(x=>`<div class="sensorrow"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");

  const b=$("battery");b.innerHTML="";
  m.temps.forEach((t,i)=>{
    const c=document.createElement("div");
    const isMeas=measuredCells.includes(i);
    c.className="cell"+(isMeas?" measured":"")+(i===5?" fault":"")+(t>48?" hot":"");
    const soh=m.cellSOH[i];
    const healthColor=soh<95?"#ef4444":soh<98?"#f59e0b":"#16a66a";
    c.innerHTML=`<div class="tag">${isMeas?"MEASURED":"DT ESTIMATE"}${i===5?"<span class=\"fault-badge\">FAULT</span>":""}</div><div class="n">CELL ${i+1}</div><div class="t">${t.toFixed(1)}°C</div><div class="h">SOC ${cellSOC[i].toFixed(1)}%</div><div class="soc">SOH ${soh.toFixed(1)}%</div><div class="healthbar"><i style="width:${soh}%;background:${healthColor}"></i></div><div class="r">R ${(i===5 ? 12*m.faultRFactor : 12*(100/soh)).toFixed(1)} mΩ</div>`;
    b.appendChild(c);
  });

  const hot=m.temps.indexOf(Math.max(...m.temps));
  $("hot").textContent="Cell "+(hot+1);
  $("soh").textContent=m.packSOH.toFixed(1)+"%";
  $("cell6soh").textContent=m.cellSOH[5].toFixed(1)+"%";
$("cell6soc").textContent=cellSOC[5].toFixed(1)+"%";
  $("res").textContent=m.resistance.toFixed(1)+" mΩ";
  const risk=m.temps[5]>45?"HIGH":m.temps[5]>40?"WATCH":"NORMAL";
  $("risk").textContent=risk;$("risk").style.color=risk==="HIGH"?"#ef4444":risk==="WATCH"?"#f59e0b":"#16a66a";
  $("explain").innerHTML=`At <b>t=${r.time_s}s</b>, the pack is <b>${mode.name}</b>. The demo starts with a deliberate <b>Cell 6 fault</b>. The DT represents the fault as increased internal resistance (<b>${(12*m.faultRFactor).toFixed(1)} mΩ</b>) and reduced effective SOH (<b>${m.cellSOH[5].toFixed(1)}%</b>), which increases I²R heating. Cell 6 is now <b>${m.temps[5].toFixed(1)}°C</b>, while the other cells remain near the normal thermal field. Pack SOC remains the BMS input; cell SOC is reconstructed by coulomb counting. Coolant thermal residual = <b>${m.residual.toFixed(2)}°C</b>.`;

  drawAllTempChart();
  drawTempChart();
  svgSocChart();
  drawHealthChart(m.cellSOH.map(soh=>({soh})));
  drawResistanceChart(m);
  drawCellSocChart(cellSOC);
  const minSoc=Math.min(...cellSOC), maxSoc=Math.max(...cellSOC);
  $("healthSummary").innerHTML=`<div class="kpi-row">
    <div class="kpi"><small>Cell SOC range</small><b>${minSoc.toFixed(1)}–${maxSoc.toFixed(1)}%</b></div>
    <div class="kpi"><small>Cell 6 SOC</small><b>${cellSOC[5].toFixed(1)}%</b></div>
    <div class="kpi"><small>Cell 6 SOH</small><b>${m.cellSOH[5].toFixed(1)}%</b></div>
  </div>`;
}
function step(){if(!data.length)return;idx++;if(idx>=data.length)idx=0;render();}
$("pause").addEventListener("click",()=>{running=false;clearInterval(timer);$("live").textContent="Ⅱ PAUSED — FAULT ACTIVE";});
